    struct entry { char const* name; char const* doc; };
    inline entry const sDocs[] =
    {
        { "", "A powerful, extensible, and easy-to-use option parser.\n\nBy Greg Ward <gward@python.net>\n\nOriginally distributed as Optik.\n\nFor support, use the optik-users@lists.sourceforge.net mailing list\n(http://lists.sourceforge.net/lists/listinfo/optik-users).\n\nSimple usage example:\n\n   from optparse import OptionParser\n\n   parser = OptionParser()\n   parser.add_option(\"-f\", \"--file\", dest=\"filename\",\n                     help=\"write report to FILE\", metavar=\"FILE\")\n   parser.add_option(\"-q\", \"--quiet\",\n                     action=\"store_false\", dest=\"verbose\", default=True,\n                     help=\"don't print status messages to stdout\")\n\n   (options, args) = parser.parse_args()\n" },
        { "AmbiguousOptionError", "\nRaised if an ambiguous option is seen on the command line.\n" },
        { "BadOptionError", "\nRaised if an invalid option is seen on the command line.\n" },
        { "HelpFormatter", "\nAbstract base class for formatting option help.  OptionParser\ninstances should use one of the HelpFormatter subclasses for\nformatting help; by default IndentedHelpFormatter is used.\n\nInstance attributes:\n  parser : OptionParser\n    the controlling OptionParser instance\n  indent_increment : int\n    the number of columns to indent per nesting level\n  max_help_position : int\n    the maximum starting column for option help text\n  help_position : int\n    the calculated starting column for option help text;\n    initially the same as the maximum\n  width : int\n    total number of columns for output (pass None to constructor for\n    this value to be taken from the $COLUMNS environment variable)\n  level : int\n    current indentation level\n  current_indent : int\n    current indentation level (in columns)\n  help_width : int\n    number of columns available for option help text (calculated)\n  default_tag : str\n    text to replace with each option's default value, \"%default\"\n    by default.  Set to false value to disable default value expansion.\n  option_strings : { Option : str }\n    maps Option instances to the snippet of help text explaining\n    the syntax of that option, e.g. \"-h, --help\" or\n    \"-fFILE, --file=FILE\"\n  _short_opt_fmt : str\n    format string controlling how short options with values are\n    printed in help text.  Must be either \"%s%s\" (\"-fFILE\") or\n    \"%s %s\" (\"-f FILE\"), because those are the two syntaxes that\n    Optik supports.\n  _long_opt_fmt : str\n    similar but for long options; must be either \"%s %s\" (\"--file FILE\")\n    or \"%s=%s\" (\"--file=FILE\").\n" },
        { "HelpFormatter._format_text", "\nFormat a paragraph of free-form text for inclusion in the\nhelp output at the current indentation level.\n" },
        { "HelpFormatter.format_option_strings", "Return a comma-separated list of option strings & metavariables." },
        { "IndentedHelpFormatter", "Format help with indented section bodies.\n    " },
        { "Option", "\nInstance attributes:\n  _short_opts : [string]\n  _long_opts : [string]\n\n  action : string\n  type : string\n  dest : string\n  default : any\n  nargs : int\n  const : any\n  choices : [string]\n  callback : function\n  callback_args : (any*)\n  callback_kwargs : { string : any }\n  help : string\n  metavar : string\n" },
        { "OptionConflictError", "\nRaised if conflicting options are added to an OptionParser.\n" },
        { "OptionContainer", "\nAbstract base class.\n\nClass attributes:\n  standard_option_list : [Option]\n    list of standard options that will be accepted by all instances\n    of this parser class (intended to be overridden by subclasses).\n\nInstance attributes:\n  option_list : [Option]\n    the list of Option objects contained by this OptionContainer\n  _short_opt : { string : Option }\n    dictionary mapping short option strings, eg. \"-f\" or \"-X\",\n    to the Option instances that implement them.  If an Option\n    has multiple short option strings, it will appear in this\n    dictionary multiple times. [1]\n  _long_opt : { string : Option }\n    dictionary mapping long option strings, eg. \"--file\" or\n    \"--exclude\", to the Option instances that implement them.\n    Again, a given Option can occur multiple times in this\n    dictionary. [1]\n  defaults : { string : any }\n    dictionary mapping option destination names to default\n    values for each destination [1]\n\n[1] These mappings are common to (shared by) all components of the\n    controlling OptionParser, where they are initially created.\n\n" },
        { "OptionContainer.destroy", "see OptionParser.destroy()." },
        { "OptionContainer.add_option", "add_option(Option)\nadd_option(opt_str, ..., kwarg=val, ...)\n" },
        { "OptionError", "\nRaised if an Option instance is created with invalid or\ninconsistent arguments.\n" },
        { "OptionGroup.destroy", "see OptionParser.destroy()." },
        { "OptionParser", "\nClass attributes:\n  standard_option_list : [Option]\n    list of standard options that will be accepted by all instances\n    of this parser class (intended to be overridden by subclasses).\n\nInstance attributes:\n  usage : string\n    a usage string for your program.  Before it is displayed\n    to the user, \"%prog\" will be expanded to the name of\n    your program (self.prog or os.path.basename(sys.argv[0])).\n  prog : string\n    the name of the current program (to override\n    os.path.basename(sys.argv[0])).\n  description : string\n    A paragraph of text giving a brief overview of your program.\n    optparse reformats this paragraph to fit the current terminal\n    width and prints it when the user requests help (after usage,\n    but before the list of options).\n  epilog : string\n    paragraph of help text to print after option help\n\n  option_groups : [OptionGroup]\n    list of option groups in this parser (option groups are\n    irrelevant for parsing the command-line, but very useful\n    for generating help)\n\n  allow_interspersed_args : bool = true\n    if true, positional arguments may be interspersed with options.\n    Assuming -a and -b each take a single argument, the command-line\n      -ablah foo bar -bboo baz\n    will be interpreted the same as\n      -ablah -bboo -- foo bar baz\n    If this flag were false, that command line would be interpreted as\n      -ablah -- foo bar -bboo baz\n    -- ie. we stop processing options as soon as we see the first\n    non-option argument.  (This is the tradition followed by\n    Python's getopt module, Perl's Getopt::Std, and other argument-\n    parsing libraries, but it is generally annoying to users.)\n\n  process_default_values : bool = true\n    if true, option default values are processed similarly to option\n    values from the command line: that is, they are passed to the\n    type-checking function for the option's type (as long as the\n    default value is a string).  (This really only matters if you\n    have defined custom types; see SF bug #955889.)  Set it to false\n    to restore the behaviour of Optik 1.4.1 and earlier.\n\n  rargs : [string]\n    the argument list currently being parsed.  Only set when\n    parse_args() is active, and continually trimmed down as\n    we consume arguments.  Mainly there for the benefit of\n    callback options.\n  largs : [string]\n    the list of leftover arguments that we have skipped while\n    parsing options.  If allow_interspersed_args is false, this\n    list is always empty.\n  values : Values\n    the set of option values currently being accumulated.  Only\n    set when parse_args() is active.  Also mainly for callbacks.\n\nBecause of the 'rargs', 'largs', and 'values' attributes,\nOptionParser is not thread-safe.  If, for some perverse reason, you\nneed to parse command-line arguments simultaneously in different\nthreads, use different OptionParser instances.\n\n" },
        { "OptionParser.destroy", "\nDeclare that you are done with this OptionParser.  This cleans up\nreference cycles so the OptionParser (and all objects referenced by\nit) can be garbage-collected promptly.  After calling destroy(), the\nOptionParser is unusable.\n" },
        { "OptionParser.enable_interspersed_args", "Set parsing to not stop on the first non-option, allowing\ninterspersing switches with command arguments. This is the\ndefault behavior. See also disable_interspersed_args() and the\nclass documentation description of the attribute\nallow_interspersed_args." },
        { "OptionParser.disable_interspersed_args", "Set parsing to stop on the first non-option. Use this if\nyou have a command processor which runs another command that\nhas options of its own and you want to make sure these options\ndon't get confused.\n" },
        { "OptionParser.parse_args", "\nparse_args(args : [string] = sys.argv[1:],\n           values : Values = None)\n-> (values : Values, args : [string])\n\nParse the command-line options found in 'args' (default:\nsys.argv[1:]).  Any errors result in a call to 'error()', which\nby default prints the usage message to stderr and calls\nsys.exit() with an error message.  On success returns a pair\n(values, args) where 'values' is a Values instance (with all\nyour option values) and 'args' is the list of arguments left\nover after parsing options.\n" },
        { "OptionParser.check_values", "\ncheck_values(values : Values, args : [string])\n-> (values : Values, args : [string])\n\nCheck that the supplied option values and leftover arguments are\nvalid.  Returns the option values and leftover arguments\n(possibly adjusted, possibly completely new -- whatever you\nlike).  Default implementation just returns the passed-in\nvalues; subclasses may override as desired.\n" },
        { "OptionParser._process_args", "_process_args(largs : [string],\n                 rargs : [string],\n                 values : Values)\n\nProcess command-line arguments and populate 'values', consuming\noptions and arguments from 'rargs'.  If 'allow_interspersed_args' is\nfalse, stop at the first non-option argument.  If true, accumulate any\ninterspersed non-option arguments in 'largs'.\n" },
        { "OptionParser._match_long_opt", "_match_long_opt(opt : string) -> string\n\nDetermine which long option string 'opt' matches, ie. which one\nit is an unambiguous abbreviation for.  Raises BadOptionError if\n'opt' doesn't unambiguously match any long option string.\n" },
        { "OptionParser.error", "error(msg : string)\n\nPrint a usage message incorporating 'msg' to stderr and exit.\nIf you override this in a subclass, it should not return -- it\nshould either exit or raise an exception.\n" },
        { "OptionParser.print_usage", "print_usage(file : file = stdout)\n\nPrint the usage message for the current program (self.usage) to\n'file' (default stdout).  Any occurrence of the string \"%prog\" in\nself.usage is replaced with the name of the current program\n(basename of sys.argv[0]).  Does nothing if self.usage is empty\nor not defined.\n" },
        { "OptionParser.print_version", "print_version(file : file = stdout)\n\nPrint the version message for this program (self.version) to\n'file' (default stdout).  As with print_usage(), any occurrence\nof \"%prog\" in self.version is replaced by the current program's\nname.  Does nothing if self.version is empty or undefined.\n" },
        { "OptionParser.print_help", "print_help(file : file = stdout)\n\nPrint an extended help message, listing all options and any\nhelp text provided with them, to 'file' (default stdout).\n" },
        { "OptionValueError", "\nRaised if an invalid option value is encountered on the command\nline.\n" },
        { "TitledHelpFormatter", "Format help with underlined section headers.\n    " },
        { "Values._update_careful", "\nUpdate the option values from an arbitrary dictionary, but only\nuse keys from dict that already have a corresponding attribute\nin self.  Any keys in dict without a corresponding attribute\nare silently ignored.\n" },
        { "Values._update_loose", "\nUpdate the option values from an arbitrary dictionary,\nusing all keys from the dictionary regardless of whether\nthey have a corresponding attribute in self or not.\n" },
        { "_match_abbrev", "_match_abbrev(s : string, wordmap : {string : Option}) -> string\n\nReturn the string key in 'wordmap' for which 's' is an unambiguous\nabbreviation.  If 's' is found to be ambiguous or doesn't match any of\n'words', raise BadOptionError.\n" },
    };
